mapper.sql:
WHERE a.occurred_at >= #{since}
AND a.resource_type = #{resourceType}
AND (UPPER(u.username) LIKE '%' || UPPER(#{actor}) || '%' ESCAPE '\' OR UPPER(u.display_name) LIKE '%' || UPPER(#{actor}) || '%' ESCAPE '\')
AND (UPPER(a.action_type) LIKE '%' || UPPER(#{keyword}) || '%' ESCAPE '\' OR UPPER(a.resource_ref) LIKE '%' || UPPER(#{keyword}) || '%' ESCAPE '\' OR UPPER(a.trace_id) LIKE '%' || UPPER(#{keyword}) || '%' ESCAPE '\')
